const a={"chhah-dhala":{id:"chhah-dhala",category:"shastra",subcategory:"charananuyoga",title:"छह ढाला (Chhah Dhala)",subtitle:"Six Shields against Transmigration by Pt. Daulatram",type:"html",content:`<div class="book-content"><p><strong>Chhah Dhala</strong> is often called the 'Gita of Jainism'. It is a precise poem of 6 Chapters (Dhalas).</p><ul><li><strong>1st Dhala:</strong> Description of the 4 Gatis (Realms) and the suffering in them.</li><li><strong>2nd Dhala:</strong> Causes of suffering - Mithyatva (False Belief).</li><li><strong>3rd Dhala:</strong> The nature of the true path (Right Faith, Knowledge, Conduct).</li><li><strong>4th Dhala:</strong> Right Faith (Samyak Darshan) in detail.</li><li><strong>5th Dhala:</strong> Right Thoughts and 12 Reflections (Bhavanas).</li><li><strong>6th Dhala:</strong> Right Conduct (Muni & Shravaka Dharma) & Liberation.</li></ul></div>`},"tattvartha-sutra":{id:"tattvartha-sutra",category:"shastra",title:"तत्त्वार्थ सूत्र (Tattvartha Sutra)",subtitle:"The Scripture of Liberation by Acharya Umaswati",type:"html",content:`<div class="book-content">\r
    <div class="sutra-quote">\r
        "सम्यग्दर्शन-ज्ञान-चारित्राणि मोक्षमार्गः" <br>\r
        (Samyak-darshana-jnana-charitrani Mokshamargah)\r
    </div>\r
    <p style="text-align: center; margin-bottom: 2rem; font-size: 1.1rem; line-height: 1.6;">\r
        The Tattvartha Sutra (Moksha Shastra) is a foundational Jain text composed by Acharya Umaswati.\r
        It condenses the essence of Jain philosophy into 10 concise chapters, beginning with the\r
        famous definition of the path to liberation: <strong>Right Faith, Right Knowledge, and Right Conduct.</strong>\r
    </p>\r
\r
    <div class="chapters-grid">\r
        <!-- Chapter 1 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 1: Faith & Knowledge</h2>\r
                <span class="chapter-num">01</span>\r
            </div>\r
            <p>Discusses the path to liberation (Moksha Marga). Introduces the seven fundamental truths\r
                (Tattvas): Jiva, Ajiva, Asrava, Bandha, Samvara, Nirjara, and Moksha. Defines the types of\r
                valid knowledge (Pramana), including sensory, scriptural, clairvoyance, telepathy, and\r
                omniscience.</p>\r
        </div>\r
\r
        <!-- Chapter 2 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 2: The Soul (Jiva)</h2>\r
                <span class="chapter-num">02</span>\r
            </div>\r
            <p>Describes the nature of the Living (Jiva) and its defining characteristic: consciousness\r
                (Upayoga). Classifies souls into liberated (Mukta) and worldly (Samsari), and further into\r
                mobile (Trasa) and immobile (Sthavara) beings. Explains the five senses and types of bodies.\r
            </p>\r
        </div>\r
\r
        <!-- Chapter 3 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 3: Lower & Middle Worlds</h2>\r
                <span class="chapter-num">03</span>\r
            </div>\r
            <p>Details Jain Cosmology (Geography). Describes the Lower World (Adholoka) with its seven hells\r
                (Narakas) and the suffering there. Describes the Middle World (Madhyaloka) where humans and\r
                animals reside, including Jambudvipa.</p>\r
        </div>\r
\r
        <!-- Chapter 4 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 4: Celestial Beings</h2>\r
                <span class="chapter-num">04</span>\r
            </div>\r
            <p>Describes the Upper World (Urdhvaloka) and the four classes of celestial beings (Devas):\r
                Mansion-dwelling, Forest-dwelling, Luminous, and Empyrean gods. Discusses their life spans,\r
                powers, and hierarchies.</p>\r
        </div>\r
\r
        <!-- Chapter 5 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 5: Non-Living (Ajiva)</h2>\r
                <span class="chapter-num">05</span>\r
            </div>\r
            <p>Explains the nature of Non-Soul substances (Ajiva): Matter (Pudgala), Medium of Motion\r
                (Dharma), Medium of Rest (Adharma), Space (Akasha), and Time (Kala). Discusses the\r
                properties of atoms (Parmanu) and molecules (Skandha).</p>\r
        </div>\r
\r
        <!-- Chapter 6 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 6: Influx (Asrava)</h2>\r
                <span class="chapter-num">06</span>\r
            </div>\r
            <p>Describes the inflow of karmic matter into the soul (Asrava). Explains how activities of\r
                mind, speech, and body (Yoga) combined with passions (Kashaya) attract karma. Distinguishes\r
                between good (Punya) and bad (Papa) influx.</p>\r
        </div>\r
\r
        <!-- Chapter 7 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 7: Vows (Vrata)</h2>\r
                <span class="chapter-num">07</span>\r
            </div>\r
            <p>Details the ethical code of conduct. Explains the five major vows (Mahavratas) for ascetics\r
                and minor vows (Anuvratas) for householders: Non-violence, Truth, Non-stealing, Celibacy,\r
                and Non-possession.</p>\r
        </div>\r
\r
        <!-- Chapter 8 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 8: Bondage (Bandha)</h2>\r
                <span class="chapter-num">08</span>\r
            </div>\r
            <p>Explains the mechanics of Karmic Bondage. Describes the four aspects of bondage: Nature\r
                (Prakriti), Duration (Sthiti), Intensity (Anubhava), and Quantity (Pradesha) of karmic\r
                particles.</p>\r
        </div>\r
\r
        <!-- Chapter 9 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 9: Stoppage & Shedding</h2>\r
                <span class="chapter-num">09</span>\r
            </div>\r
            <p>Discusses Samvara (Blocking influx) and Nirjara (Shedding karma). Explains methods like the\r
                10 Dharmas, 12 Contemplations (Bhavanas), 22 Endurances (Parishaha), and Austerities (Tapas)\r
                to purify the soul.</p>\r
        </div>\r
\r
        <!-- Chapter 10 -->\r
        <div class="chapter-card">\r
            <div class="chapter-header">\r
                <h2 class="chapter-title">Chapter 10: Liberation (Moksha)</h2>\r
                <span class="chapter-num">10</span>\r
            </div>\r
            <p>Describes the ultimate state of Moksha. When all karma is annihilated, the soul rises to the\r
                summit of the universe (Siddhashila). Describes the nature of Siddhas—infinite knowledge,\r
                perception, bliss, and power.</p>\r
        </div>\r
    </div>\r
</div>`},"ratnakarand-shravakachar":{id:"ratnakarand-shravakachar",category:"shastra",title:"रत्नकरण्ड श्रावकाचार (Ratnakarand Shravakachar)",subtitle:"The Householder's Conduct by Acharya Samantabhadra",type:"html",content:`<div class="book-content">\r
    <div class="sutra-quote">\r
        "नमः श्रीवर्धमानाय निर्धूतकलिलात्मने।<br>\r
        सालोकानां त्रिलोकानां यद्विद्या दर्पणायते॥"\r
    </div>\r
    <p style="text-align: center; margin-bottom: 2rem; font-size: 1.1rem; line-height: 1.6;">\r
        The <strong>Ratnakarand Shravakachar</strong> is a seminal work by Acharya Samantabhadra (c. 2nd\r
        century CE).\r
        It serves as the definitive manual for the Jain householder (Shravaka), explaining how to lead a\r
        virtuous life while living in the world, balancing spiritual duties with worldly responsibilities.\r
    </p>\r
\r
    <div class="chapters-grid">\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">1. The Three Jewels (Ratnatraya)</h2>\r
            <p>The text begins by establishing that the path to liberation consists of Right Faith (Samyak\r
                Darshan), Right Knowledge (Samyak Jnana), and Right Conduct (Samyak Charitra). These three\r
                must exist together like a jewel (Ratna) to lead to Moksha.</p>\r
        </div>\r
\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">2. Right Faith (Samyak Darshan)</h2>\r
            <p>Defined as true belief in the seven fundamental truths (Tattvas) free from three follies\r
                (Moodyata), eight pride (Mada), and six imperfections (Anayatan). A true believer worships\r
                only the Vitaraga (passionless) God, the Nirgrantha (possession-less) Guru, and the\r
                Anekantavadi (non-absolutist) Scripture.</p>\r
        </div>\r
\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">3. The 12 Vows of a Householder</h2>\r
            <p>The core of the text describes the ethical code for laypeople:</p>\r
            <ul>\r
                <li><strong>5 Anuvratas (Minor Vows):</strong> Non-violence, Truth, Non-stealing, Celibacy,\r
                    Non-possession.</li>\r
                <li><strong>3 Gunavratas (Merit Vows):</strong> Limiting spatial boundaries, limiting\r
                    consumables, and avoiding purposeless sins (Anarthadanda).</li>\r
                <li><strong>4 Shikshavratas (Disciplinary Vows):</strong> Samayik (meditation), Prosadhopvas\r
                    (fasting), Bhogopabhoga (limits on usage), and Atithi Samvibhag (charity).</li>\r
            </ul>\r
        </div>\r
\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">4. Sallekhana (Holy Death)</h2>\r
            <p>The text explains the art of dying with dignity. Sallekhana is not suicide, but a spiritual\r
                vow taken towards the end of life to shed the body peacefully with complete detachment and\r
                awareness, removing the fear of death.</p>\r
        </div>\r
\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">5. Eleven Pratimas (Stages of Progress)</h2>\r
            <p>It outlines 11 stages of spiritual development for a householder, starting from having Right\r
                View (Darshan Pratima) to completely renouncing the household (Uddishta Tyag Pratima) to\r
                become a monk.</p>\r
        </div>\r
    </div>\r
</div>`},samaysar:{id:"samaysar",category:"shastra",title:"समयसार (Samaysar)",subtitle:"The Essence of the Self by Acharya Kundakunda",type:"html",content:`<div class="book-content">\r
    <div class="sutra-quote">\r
        "वंदित्तु सव्वसिद्धे धुवमचलमणोवमं गदिं पत्ते।<br>\r
        वोच्छामि समयपाहुडमिणमो सुदकेवलीभणिदं॥"\r
    </div>\r
    <p style="text-align: center; margin-bottom: 2rem; font-size: 1.1rem; line-height: 1.6;">\r
        <strong>Samaysar</strong> is the magnum opus of Acharya Kundakunda (c. 1st century CE). It is a\r
        spiritual masterpiece that\r
        focuses entirely on the nature of the Pure Soul (Shuddha Atma). It distinguishes between the\r
        worldly self (entangled in Karma) and the true, eternal self (Paramatma).\r
    </p>\r
\r
    <div class="chapters-grid">\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">The Central Teaching</h2>\r
            <p>The core message of Samaysar is that the Soul (Jiva) is pure, omniscient, and blissful by\r
                nature. All impurities (Karma, passions, body) are alien to it. Realizing this distinction\r
                (Bheda-Vijnana) is the key to liberation.</p>\r
        </div>\r
\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">Jiva vs. Ajiva</h2>\r
            <p>It rigorously separates the 'knower' (the soul) from the 'known' (the objects/karmas). The\r
                soul is the eternal knower and seer, while everything else (body, emotions, thoughts) is\r
                external and transient.</p>\r
        </div>\r
\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">Two Viewpoints (Nayas)</h2>\r
            <p>Kundakunda explains reality from two perspectives:</p>\r
            <ul>\r
                <li><strong>Vyavahara Naya (Practical Point of View):</strong> Sees the soul as bound by\r
                    karma, doing good/bad deeds.</li>\r
                <li><strong>Nishchaya Naya (Real Point of View):</strong> Sees the soul as eternally pure,\r
                    unbound, and complete. This is the view to be meditated upon for enlightenment.</li>\r
            </ul>\r
        </div>\r
\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">Karma and Bondage</h2>\r
            <p>The text explains that it is not the external action, but the internal attachment (Raga) and\r
                aversion (Dvesha) that bind the soul. A dispassionate observer (Sakshi) remains unbound even\r
                while acting.</p>\r
        </div>\r
\r
        <div class="chapter-card">\r
            <h2 class="chapter-title">The Path to Moksha</h2>\r
            <p>Liberation is achieved by resting the attention on the pure nature of the Self, disregarding\r
                the distractions of the Karmic self. This self-absorption (Atma-Dhyana) leads to the\r
                destruction of all Karmas.</p>\r
        </div>\r
    </div>\r
</div>`},"padma-puran":{id:"padma-puran",category:"shastra",subcategory:"prathamanuyoga",title:"पद्म पुराण (Jain Ramayana)",subtitle:"The Life of Lord Rama by Acharya Ravishena",type:"html",content:'<div class="book-content"><p><strong>Padma Puran</strong> is the Jain version of the Ramayana. It focuses on the life of <strong>Padma (Rama)</strong>, a Balabhadra, and his journey. Unlike other versions, it emphasizes the law of Karma and Non-violence. It describes Ravana as a Prati-Narayana (tragic hero) who was a devout Jain but fell due to passion. Ultimately, Rama attains Moksha, and Hanuman enters the ascetic order.</p></div>'},"harivansh-puran":{id:"harivansh-puran",category:"shastra",subcategory:"prathamanuyoga",title:"हरिवंश पुराण (Jain Mahabharata)",subtitle:"Lineage of Lord Krishna & Neminath by Acharya Jinasena",type:"html",content:'<div class="book-content"><p><strong>Harivansh Puran</strong> narrates the history of the Harivansh dynasty, focusing on the 22nd Tirthankara <strong>Lord Neminath</strong> and his cousin <strong>Lord Krishna</strong> (Narayana). It details the Mahabharata war from a Jain perspective, explaining the past lives and karmic causes of the Pandavas and Kauravas. It emphasizes that Krishna will become a future Tirthankara.</p></div>'},"trilok-saar":{id:"trilok-saar",category:"shastra",subcategory:"karananuyoga",title:"त्रिलोक सार (Trilok Saar)",subtitle:"Essence of the Three Worlds by Acharya Nemichandra",type:"html",content:'<div class="book-content"><p><strong>Trilok Saar</strong> is a monumental text describing the structure of the Universe (Teen Lok) in mathematical detail. It gives precise measurements of the Hells, Middle World (islands/oceans), and Heavens. It explains the lifespans, heights, and types of beings in each realm, serving as a definitive guide to Jain Cosmology.</p></div>'},"purushartha-siddhipaya":{id:"purushartha-siddhipaya",category:"shastra",subcategory:"charananuyoga",title:"पुरुषार्थ सिद्ध्युपाय",subtitle:"Means to Achieve the Ultimate Goal by Acharya Amritchandra",type:"html",content:'<div class="book-content"><p><strong>Purushartha Siddhipaya</strong> deals with the conduct of the householder (Shravaka). It famously defines Himsa (violence) as the emergence of passions (Rag-Dvesha) and Ahimsa as the absence of them. It provides a logical and psychological analysis of the vows, explaining <em>why</em> we should follow them for our own peace.</p></div>'},mulachar:{id:"mulachar",category:"shastra",subcategory:"charananuyoga",title:"मूलाचार (Mulachar)",subtitle:"Root of Conduct by Acharya Vattakera",type:"html",content:'<div class="book-content"><p><strong>Mulachar</strong> is considered the primary text for Digambara Monastic Conduct. It details the 28 Mula Gunas (Fundamental Virtues) of a monk, rules of alms-begging (Ahara), sleeping, walking, and meditation. It is essentially the rulebook for the ascetic life.</p></div>'},pravachanasar:{id:"pravachanasar",category:"shastra",subcategory:"dravyanuyoga",title:"प्रवचनसार (Pravachanasar)",subtitle:"Essence of Doctrine by Acharya Kundakunda",type:"html",content:'<div class="book-content"><p><strong>Pravachanasar</strong> is divided into three sections: Knowledge (Jnana), Knowable (Jneya), and Conduct (Charitra). It explains the nature of Omniscience (Kevala Jnana) and proves that the soul knows all things simultaneously without the senses. It also discusses the nature of substances (Dravya) and the path of happiness.</p></div>'},niyamasar:{id:"niyamasar",category:"shastra",subcategory:"dravyanuyoga",title:"नियमसार (Niyamasar)",subtitle:"The Review of Rules by Acharya Kundakunda",type:"html",content:`<div class="book-content"><p><strong>Niyamasar</strong> focuses on the 'Niyama' (Rule) which is the path to liberation: Right Faith, Knowledge, and Conduct. It emphasizes the outcome of these—<strong>Supreme Meditation (Param-Samadhi)</strong>. It clearly distinguishes between the impure modifications of the mind and the pure nature of the self.</p></div>`},ashtasahasri:{id:"ashtasahasri",category:"shastra",subcategory:"dravyanuyoga",title:"अष्टसहस्री (Ashtasahasri)",subtitle:"8000 Verses on Logic by Acharya Vidyanandi",type:"html",content:'<div class="book-content"><p><strong>Ashtasahasri</strong> is a complex treatise on Jain Logic (Nyaya). It is a commentary on <em>Aptamimamsa</em>. It logically refutes the one-sided views of other schools of thought (like Nihilism, Eternalism) and establishes <strong>Syadvada</strong> (Theory of Relativity) as the only logical way to describe reality.</p></div>'},"moksha-marg-prakashak":{id:"moksha-marg-prakashak",category:"shastra",subcategory:"dravyanuyoga",title:"मोक्षमार्ग प्रकाशक",subtitle:"Illuminator of the Path of Liberation by Pt. Todarmal",type:"html",content:'<div class="book-content"><p><strong>Moksha Marg Prakashak</strong> is a masterpiece of logic and psychology. Pt. Todarmal Ji explains <em>why</em> we are unhappy (karmic bondage due to delusion) and <em>how</em> to solve it. He critiques various false beliefs (Grihit & Agrihit Mithyatva) and explains the nature of the Omniscient God (Arihanta) vs. worldly deities.</p></div>'},"dravya-sangrah":{id:"dravya-sangrah",category:"shastra",subcategory:"dravyanuyoga",title:"द्रव्य संग्रह (Dravya Sangrah)",subtitle:"Compendium of Substances by Acharya Nemichandra",type:"html",content:`<div class="book-content"><p><strong>Dravya Sangrah</strong> provides a concise definition of the <strong>6 Dravyas</strong> (Soul, Matter, Medium of Motion, Medium of Rest, Space, Time) and the <strong>7 Tattvas</strong>. It explains the nature of the Soul (Jiva) as 'Upayogamayi' (Characterized by consciousness) and 'Amurtik' (Non-material).</p></div>`}};export{a as ShastraData};
